use serde_json::{Value,json};use std::{fs,path::Path,fmt::Write};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn main(){let r=Path::new("/tmp/zopro-lower-bound-c7a");let a=read(r.join("analysis.json"));let root=Path::new("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-26-lower-bound-c7a");assert_eq!(a["post_transport_gnark_verified"],272);let p64=&a["cases"]["1x2-w64"]["engines"]["on"];let ag96=&a["cases"]["1x2-w96"]["engines"]["aeglos"];let base=&a["cases"]["1x2-w32"]["engines"]["accepted"];let mut t=String::from("# C7a comparison if the bitmap candidate is accepted\n\nThis is the measured outcome **assuming we accept the candidate**. It is a proposed-adoption report; production has not been changed. The candidate passes proof verification, but the full performance qualification fails calibration and several regression checks. Those limitations remain part of the result.\n\n");
 writeln!(t,"The best tested 1→2 configuration is **{:.3} ms at 64 workers**, with **{:.1} MiB peak process RSS**. Aeglos's best tested result is **{:.3} ms at 96 workers**, with **{:.1} MiB RSS**. Aeglos remains {:.2}× faster on this small proof; the candidate uses {:.2}× less measured RSS. Against the accepted Zopro build's best tested {:.3} ms at 32 workers, selecting the candidate's best tested configuration improves latency by {:.2}%.\n",p64["request_ms"].as_f64().unwrap(),p64["maximum_whole_process_RSS_mib"].as_f64().unwrap(),ag96["request_ms"].as_f64().unwrap(),ag96["maximum_whole_process_RSS_mib"].as_f64().unwrap(),p64["request_ms"].as_f64().unwrap()/ag96["request_ms"].as_f64().unwrap(),ag96["maximum_whole_process_RSS_mib"].as_f64().unwrap()/p64["maximum_whole_process_RSS_mib"].as_f64().unwrap(),base["request_ms"].as_f64().unwrap(),100.*(1.-p64["request_ms"].as_f64().unwrap()/base["request_ms"].as_f64().unwrap())).unwrap();
 t.push_str("The candidate wins on **six of nine measured shapes** against Aeglos when each uses its best tested worker count. Aeglos wins on 1→2, 2→2 and 4→2. Zopro's advantage on larger shapes and lower memory use mostly existed before this candidate; they should not be attributed to the bitmap change.\n\n## Candidate versus Aeglos\n\nDedicated c7a.24xlarge, 96 physical cores, 30 GiB container. Each result is the median of three fresh-process medians. Every proof includes fresh witness solving, randomness, proving, SDK verification and serialization. Loading and preparation are excluded from latency. Workers are chosen from the tested counts: 32/64/96 for 1→2, and 64/96 for other shapes. This is a descriptive selection, not an implemented automatic worker policy.\n\n| Shape | Candidate ms | Workers | Aeglos ms | Workers | Candidate RSS MiB | Aeglos RSS MiB |\n|---|---:|---:|---:|---:|---:|---:|\n");
 let shapes=["1x2","2x2","4x2","8x2","12x2","16x2","24x2","merge-24x1","merge-54x1"];let mut selected=Vec::new();let mut wins=0;let mut min_mem=f64::INFINITY;let mut max_mem=0f64;
 for shape in shapes{let cases:Vec<_>=a["cases"].as_object().unwrap().values().filter(|c|c["shape"]==shape).collect();let best=|mode:&str|*cases.iter().min_by(|x,y|x["engines"][mode]["request_ms"].as_f64().unwrap().total_cmp(&y["engines"][mode]["request_ms"].as_f64().unwrap())).unwrap();let z=best("on");let ag=best("aeglos");let ze=&z["engines"]["on"];let ae=&ag["engines"]["aeglos"];let ms=ze["request_ms"].as_f64().unwrap();let ams=ae["request_ms"].as_f64().unwrap();let mem=ze["maximum_whole_process_RSS_mib"].as_f64().unwrap();let amem=ae["maximum_whole_process_RSS_mib"].as_f64().unwrap();if ms<ams{wins+=1;}min_mem=min_mem.min(amem/mem);max_mem=max_mem.max(amem/mem);writeln!(t,"|{shape}|{ms:.3}|{}|{ams:.3}|{}|{mem:.1}|{amem:.1}|",z["workers"],ag["workers"]).unwrap();selected.push(json!({"shape":shape,"candidate":z,"aeglos":ag}));}assert_eq!(wins,6);writeln!(t,"\nAt these configurations, candidate RSS is **{min_mem:.1}–{max_mem:.1}× lower** than Aeglos. RSS is the maximum whole process, including load/setup/primes; it is not minimum required RAM, an allocation bound or a phone measurement.\n").unwrap();
 t.push_str("## What accepting this candidate changes\n\nThe candidate avoids some full scalar-grouping hash maps that would be discarded. It first counts occupied bits in a temporary 16–64 KiB bitmap. Occupancy is an exact lower bound on distinct nonzero scalars; collisions only fall back to the existing code. The grouping cutoff and proving math stay the same. The bitmap fits the existing grouping memory forecast, is released before full map allocation, and is not a retained key table.\n\nThe change has a larger effect on 1→2 with many C7a workers than on the local 32-thread Ryzen. Same-worker results:\n\n| Workers | Accepted Zopro ms | Candidate ms | Paired gain versus accepted | Paired gain versus candidate OFF |\n|---|---:|---:|---:|---:|\n");for w in [32,64,96]{let c=&a["cases"][format!("1x2-w{w}")];writeln!(t,"|{w}|{:.3}|{:.3}|{:.2}%|{:.2}%|",c["engines"]["accepted"]["request_ms"].as_f64().unwrap(),c["engines"]["on"]["request_ms"].as_f64().unwrap(),100.*(1.-c["on_accepted_geomean"].as_f64().unwrap()),100.*(1.-c["on_off_geomean"].as_f64().unwrap())).unwrap();}
 t.push_str("\nThese paired gains are geometric means of block ratios; they can differ from ratios of the displayed medians. At 32 workers there is no meaningful ON/OFF improvement. The 64-worker candidate uses more summed CPU per proof than accepted Zopro at 32 workers, despite its slightly lower latency:\n\n| Configuration | CPU ms per proof, summed over threads |\n|---|---:|\n");writeln!(t,"|Accepted Zopro, 32 workers|{:.1}|\n|Candidate, 64 workers|{:.1}|\n|Aeglos, 96 workers|{:.1}|\n",base["CPU_ms_per_request"].as_f64().unwrap(),p64["CPU_ms_per_request"].as_f64().unwrap(),ag96["CPU_ms_per_request"].as_f64().unwrap()).unwrap();t.push_str("CPU includes coordination and spinning. Concurrent-proof throughput was not measured, so the fastest single-proof setting should not automatically become the server-wide default.\n\nUsing the candidate requires the `zopro_grouping_lower_bound` build flag and `ZOPRO_CPU_GROUPING_LOWER_BOUND=1`; the complete tested flags and environment are pinned in the benchmark artifacts. The 64-worker setting above is supported only as the best tested single-proof 1→2 result.\n\n## Supplied M5 comparison\n\nM5 values are historical user-supplied references, not fresh Apple measurements. These ratios use candidate best-tested latency. No M5 reference was supplied for 54→1.\n\n| Shape | Candidate ms | M5 CPU ms | CPU speedup | M5 Metal ms | Metal speedup |\n|---|---:|---:|---:|---:|---:|\n");let mut achieved=0;
 for row in &selected{let c=&row["candidate"];let ms=c["engines"]["on"]["request_ms"].as_f64().unwrap();let reference=&c["reference"];let shape=row["shape"].as_str().unwrap();if reference.is_object(){let cpu=reference["cpu_ms"].as_f64().unwrap();let metal=reference["metal_ms"].as_f64().unwrap();if cpu/ms>=10.{achieved+=1;}writeln!(t,"|{shape}|{ms:.3}|{cpu:.0}|{:.2}×|{metal:.0}|{:.2}×|",cpu/ms,metal/ms).unwrap();}else{writeln!(t,"|{shape}|{ms:.3}|—|—|—|—|").unwrap();}}writeln!(t,"\n**The all-eight CPU 10× goal is unmet: {achieved}/8 rows reach it.** For 1→2, the target is 3.7 ms; the candidate's 12.096 ms still requires about a further 3.27× latency reduction. This candidate is an incremental optimization.\n").unwrap();
 t.push_str("## Acceptance limits\n\nAll proof checks pass: **5,640 SDK calls, 272 distinct independently Gnark-verified exports across nine keys**, and all 272 exports verify again locally after transport. The fresh target build passes 113 core tests and the raw/cubic proof tests.\n\nThe full predeclared performance gate fails. Primary 64/96 speed checks pass, but some OFF/accepted calibration checks fail and several other shapes are slower against the accepted build. Across the original eight shapes, paired ON/accepted aggregate latency changes by:
\n");for w in [64,96]{let ratio=a["original_eight_aggregates"][w.to_string()]["on_accepted_geomean"].as_f64().unwrap();writeln!(t,"- {w} workers: {:+.2}% (positive is slower).",100.*(ratio-1.)).unwrap();}
 t.push_str("\nAccepting the results therefore does not support describing this as a general prover speedup. The evidence supports a small-proof benefit on C7a with many workers, while broader adoption needs those calibration/regression concerns resolved. There are no new phone, TEE, concurrent-throughput, memory-pressure or huge-circuit measurements.\n\nThe whole workflow also records some CPU quota throttling; per-case attribution is unavailable. It is not established as the cause of any regression. Exact counters, all block ratios and every failed check are in the [full benchmark report](README.md) and its [analysis](artifacts/analysis.json).\n\nThe owned AWS instance and temporary storage/image/transfer resources are cleaned up. **This report assumes acceptance for comparison; the candidate remains unadopted and production source is unchanged.**\n");fs::write(root.join("PROPOSED-ADOPTION.md"),t).unwrap();println!("Wrote conditional adoption report:9shapes,6wins,all8M5comparisons,failedchecksretained");}
